# Tengai Makyou: Fuun Kabuki-den - English patch EN-v1.0.22 (chiffres boutiques)
# Usage: place this script next to the game's .cue/.bin files, then right-click > "Run with PowerShell"
$ErrorActionPreference = "Stop"
$dir  = Split-Path -Parent $MyInvocation.MyCommand.Path
$name = "Far East of Eden - Tengai Makyou - Fuun Kabuki-den (Japan)"
$src  = Join-Path $dir "$name (Track 02).bin"
$dst  = Join-Path $dir "$name (Track 02) [EN-v1.0.22].bin"
$cue  = Join-Path $dir "$name.cue"
$ncue = Join-Path $dir "$name [EN-v1.0.22].cue"
if (!(Test-Path -LiteralPath $src)) { Write-Host "Track 02 introuvable : $src"; Read-Host "Entree pour quitter"; exit 1 }
Write-Host "Verification de la piste originale..."
$h = (Get-FileHash -LiteralPath $src -Algorithm MD5).Hash
if ($h -ne "EC992A55A340F7D11726D09E3CB7051D") { Write-Host "Attention : la piste 02 ne correspond pas au dump attendu ($h)."; Read-Host "Entree pour quitter"; exit 1 }
Copy-Item -LiteralPath $src -Destination $dst -Force
