foreach ($p in $patches) { $b = [Convert]::FromBase64String($p.Data); $fs.Position = $p.Offset; $fs.Write($b, 0, $b.Length) }
$fs.Close()
$h2 = (Get-FileHash -LiteralPath $dst -Algorithm MD5).Hash
if ($h2 -ne "39E2AD47720EC0923FDE489FB5BD2206") { Write-Host "Erreur : resultat inattendu ($h2)"; Read-Host "Entree pour quitter"; exit 1 }
